onClick:
{{ (async () => { try {
 const kind=selCompanyDonorContactKind.selectedOptionValue;
 if(kind==='address') {
   const street=inpCompanyAddressStreet.text?.trim(); const unit=inpCompanyAddressUnit.text?.trim() || null;
   const city=inpCompanyAddressCity.text?.trim(); const state=inpCompanyAddressState.text?.trim();
   const postal=inpCompanyAddressPostal.text?.trim(); const country=inpCompanyAddressCountry.text?.trim() || 'USA';
   const reason=inpCompanyDonorContactReason.text?.trim() || inpCompanyAddressReason.text?.trim();
   if(!street || !city || !state || !postal || !reason) {showAlert('Enter an address and reason.','warning');return;}
   const r=await qAddCompanyDonorAddress.run({street,unit,city,state,postal,country,reason});
   if(!r?.[0]?.address_id) throw new Error('Address was not added.');
   await Promise.all([qCompanyDonorAddresses.run(),qCompanyContacts.run()]);
 } else {
   const reason=inpCompanyDonorContactReason.text?.trim(); const value=inpCompanyDonorContactValue.text?.trim();
   if(!reason || !value || !['email','phone'].includes(kind)) {showAlert('Enter a contact and reason.','warning');return;}
   const r=await qAddCompanyDonorContact.run({kind,value,reason});
   if(!r?.[0]?.contact_id) throw new Error('Contact was not added.');
   await Promise.all([qCompanyDonorContacts.run(),qCompanyContacts.run(),qCompanyProfile.run()]);
 }
 showAlert('Contributor contact added.','success');
} catch(e) {showAlert('Contact change failed: '+(e?.message||e),'error');} })() }}
